            if (a1 < -thS - 0.03 || a0 > thS + 0.03) continue;
            const alpha = Math.min(1, w.lum * Lr.lumK * (0.3 + 0.7 * Math.min(1, w.len * 1.8)) * C.beamBright * (Lr.dyn === 'bounce' ? C.beamBounce : 1)) * bldG;
            if (alpha < 0.005) continue;
