          const a = rr(-thS, thS) * 0.95, rawN = Math.max(1, Math.round((14 + (rnd() * 30 | 0)) * C.burstSize));
          const n = lowPowerNow ? Math.max(1, Math.round(rawN * 0.55)) : rawN;
