          for (let i = flares.length - 1; i >= 0; i--) { flares[i].age += dtM; if (flares[i].age > flares[i].life) flares.splice(i, 1); }
          if (actOn && rnd() < Math.min(0.9, 3.6 * dtM * C.flareRate)) spawnFlare();
