        instTps: 0,
        totalTokens: 0,
        inputTokens: 0,
        outputTokens: 0,
        contextTokens: 0,
        contextLimit: 0,
        approvalPending: false,
        approvalRequest: null,
        questionPending: false,
        questionPrompt: null,
        todayKey: '',
        todayUsage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
        sessionUsage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
        turnUsage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
        compactions: 0,
        prunes: 0,
        cacheReadTokens: 0,
        cacheWriteTokens: 0,
        uncachedInputTokens: 0,
        cacheHit: 0,
        cacheHitNative: 0,
        hasCacheHitNative: false,
        reasoning: '',
        reasoningAt: 0,
        series: [],
        turn: 0,
        step: 0,
        model: '',
        sessionTitle: '',
        sessionId: undefined,
        tools: [],
        toolCalls: 0,
        toolResults: 0,
        lastToolEventAt: 0,
        sourceError: false,
        feed: [],
        tokenQueue: [],
        recentTokens: [],
        recentText: '',
