        live.tps = 0;
        live.instTps = 0;
        live.tools.length = 0;
        live.toolCalls = 0;
        live.toolResults = 0;
        live.lastToolEventAt = 0;
        live.sessionUsage = emptyUsage();
        live.turnUsage = emptyUsage();
        live.compactions = 0;
        live.prunes = 0;
        live.approvalPending = false;
        live.approvalRequest = null;
        live.questionPending = false;
        live.questionPrompt = null;
        compactionIds = new Set();
